{ 
  "description": "The creature is shown in right-facing profile standing on pale ground. It has the head, fur and paws of a wolf on a quadrupedal body that is almost entirely covered in dark gray to black glossy overlapping segmented armor. A very long, thick, plate-covered neck arches up and forward from the shoulders, loops back on itself over the back, and connects to the wolf-like head at the right end. The dorsal and lateral surfaces, the outer sides of the legs, the tail and a small patch on the forehead are covered in large overlapping plates, while the ventral chest, belly and inner legs show paler segmented skin with a row of small oval openings along the flank. The overall impression is a single continuous wolf-like quadruped encased in woodlouse/isopod-like armor with two thin antennae on the forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like with dense gray, white and tan fur, elongated pointed muzzle, black nose, slightly open mouth, and one visible light amber eye",
      "where": "at the far right end of the long arched neck, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, furry ears with dark interiors and gray outer fur",
      "where": "on top of the head, behind the forehead plates"
    },
    {
      "part": "horns/antennae",
      "looks_like": "two thin, brownish, slightly segmented, filament-like antennae curving forward",
      "where": "protruding from the forehead just in front of the small forehead plates, between the ears and the eyes"
    },
    {
      "part": "mane/ruff",
      "looks_like": "thick shaggy gray and white fur ruff",
      "where": "encircling the base of the head where the fur meets the plated neck"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy quadrupedal legs with dark glossy plated armor on the dorsal/outer surfaces and pale furry skin on the ventral/inner surfaces, jointed at shoulder/hip and knee/hock",
      "where": "two forelegs under the chest and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large paw-like feet with pale fur, distinct toes and short dark claws",
      "where": "at the distal ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, tapering, heavily armored tail made of overlapping dark plates with a serrated ventral edge, narrowing to a pointed tip",
      "where": "extending from the rear of the body and curving downward to the right"
    },
    {
      "part": "plates/shell",
      "looks_like": "dark slate-gray to black glossy overlapping segmented plates/scutes, large and shield-like on the neck, back and sides, smaller and band-like on the legs and tail, and 3-4 small plates on the forehead; the ventral belly shows lighter cream-colored segmented plates",
      "where": "covering the entire dorsal neck, back, sides, outer legs, tail and forehead; ventral side lighter"
    },
    {
      "part": "markings/openings",
      "looks_like": "a longitudinal row of 7 small oval dark openings (spiracles) set in the pale lateral plates",
      "where": "along the lower flank between the fore and hind legs on the visible right side"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "woodlouse"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 2,
  "tails": 1
}
